INSERT INTO patients (id, global_user_id, phone, emergency_phone, address, age_range, relationship_status, occupation_type, living_situation, primary_goal, has_previous_therapy) VALUES (3, 'u_pat12', '+1313131313', '+1313131314', 'Carrera 12', '18-25', 'Soltero', 'Estudiante', 'Vive con padres', 'Dificultades de socialización y timidez extrema', FALSE);
INSERT INTO treatments (id, patient_id, state) VALUES (1, 1, 'ACTIVE');
INSERT INTO treatments (id, patient_id, state) VALUES (2, 2, 'ACTIVE');
INSERT INTO treatments (id, patient_id, state) VALUES (3, 3, 'ACTIVE');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-16', 'audio', 'Día 1: Hoy fue un día realmente complicado. Me desperté sintiéndome frustrado porque sabía que tenía que entregarle un trabajo a mi profesor, pero por alguna razón, simplemente no podía concentrarme en ello. Mientras hacía el esfuerzo, mis padres comenzaron a discutir sobre un tema trivial en la cocina, y eso me llevó a perder la paciencia. Me sentí tan enojado que estuve a punto de gritarles. Mi corazón latía rápido, y no sé... solo deseaba que el ruido se detuviera. Al final, decidí salir a caminar un rato. Supongo que eso me ayudó un poco a calmarme, pero aún así, sentí que no logré controlar mi ira como debería. Es frustrante. Estoy comenzando a preguntarme si puedo cambiar esto.', 'Es comprensible que te sientas abrumado, Lucas. La convivencia familiar puede generar mucha tensión, y es natural que esas discusiones te afecten emocionalmente. Darte un tiempo para ti mismo, como salir a caminar, es una buena estrategia para manejar esas emociones. Reconocer cómo te sientes es el primer paso hacia un cambio positivo. No te desanimes, cada pequeño esfuerzo cuenta.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-17', 'audio', 'Día 2: Hoy me sentí un poco mejor, aunque aún con un tono de tensión. En la escuela, noté que uno de mis amigos hizo un comentario que me molestó, y en lugar de reaccionar como antes, simplemente me reí de la situación. Quiero pensar que esa es una pequeña victoria, pero después del día, me sentí cansado emocionalmente. Al llegar a casa, mi papá me preguntó sobre la tarea y eso destruyó completamente mi ánimo. Le contesté de forma grosera, me siento mal por eso. No sé, creo que la ira es algo muy difícil de manejar. Tal vez estoy avanzando, pero la montaña sigue ahí.', 'Lucas, es genial escuchar que pudiste manejar la situación con tu amigo, eso es un paso hacia adelante. Sin embargo, es completamente normal tener momentos de retroceso, especialmente en casa. Aprende a ser amable contigo mismo; el camino hacia el cambio no es lineal y cada día trae sus propios desafíos. Reflexionar sobre las reacciones que tienes puede ayudarte a identificar opciones diferentes. Te animo a seguir trabajando en ti mismo.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-18', 'audio', 'Día 3: Hoy... eh, en realidad fue bastante caótico. Recibí un examen que no me esperaba y eso me puso nervioso. Me sentía como si todas mis emociones de ira y ansiedad se apilaran dentro de mí. En el almuerzo, discutí con una de mis amigas sobre un tema que, ya sabemos, no tan importante. Cuando terminamos de hablar, me quedé con un mal sabor en la boca. Me doy cuenta de que la ira no solo se manifiesta con mi familia. Todo parece estar conectado. En un momento de rabia, tiré mis cosas al suelo y luego me sentí completamente estúpido por hacerlo. Me siento cansado de estar tan a la orilla de estallar todo el tiempo.', 'Es natural sentir que las emociones se agolpan, Lucas. El estrés de los exámenes y la presión social pueden ser abrumadores. Reconocer que tu ira se manifiesta en diferentes entornos es una parte importante de tu proceso. Lo que hiciste al tirar tus cosas refleja la necesidad de liberar esa tensión que llevas dentro. Te animo a encontrar formas más saludables de expresar lo que sientes; puedes dedicar tiempo a escribir o practicar respiración consciente. A veces, pequeñas acciones pueden marcar una gran diferencia.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-19', 'text', 'Día 4: Hoy fue un día bastante tranquilo en comparación. Fui al parque a estudiar porque necesitaba un cambio de escenario. Mientras estaba allí, me puse a pensar en todos los problemas que tengo. La ira, la rebeldía… todo me abruma de vez en cuando. Pero, de alguna manera, me sentí en paz solo escuchando el sonido de los pájaros. Volviendo a casa, me encontré con mi mamá y decidí hablar con ella sobre cómo me sentía al respecto. Para mi sorpresa, me escuchó sin interrumpir. Sentí que pude abrirme un poco, y eso me alivió. Aún así, no sé si eso realmente cambiará algo...', 'Es maravilloso escuchar que encontraste un espacio tranquilo y que te permitiste abrirte con tu mamá. Esto muestra un gran crecimiento emocional y disposición para conectar. Hablar sobre lo que sientes, incluso solo un poco, puede ayudar muchísimo a aliviar la carga emocional. Recuerda que cada paso que das, por pequeño que sea, es progresar hacia tu meta. No subestimes la importancia de esos momentos de vulnerabilidad.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-20', 'text', 'Día 5: La ira me invade nuevamente, y pensé que estaba mejorando. Mi profesor me dijo que tenía que entregar un proyecto extra justo antes de la fecha de entrega. Me quedé sin palabras. Dentro de mí, sentí como si la furia estuviera a punto de explotar. Cuando llegué a casa, simplemente entré y grité. Mis padres se asustaron y eso me hizo sentir aún más culpable. No sé, creo que no tengo control sobre mí mismo. Yo quiero cambiar, pero a veces parece que retrocedo más que avanzar. Me pregunto si todo esto vale la pena.', 'Es normal experimentar altibajos en este proceso, Lucas. El hecho de que sientas esa ira intensa es un indicador de que estás trabajando en tus emociones. Gritar puede ser una respuesta impulsiva, pero también puede revelar cuán agobiado te sientes. Permítete sentir esos momentos y reflexionar sobre ellos, en lugar de juzgarte. La transformación llevará tiempo, y es crucial mantener la esperanza y la determinación en tu viaje. Estás en el camino correcto al reconocer tus emociones.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-22', 'audio', 'Día 6: Hoy decidí dejar de lado el estrés por un rato y enfocarme en algo que disfruto: la música. Escuché algunas de mis canciones favoritas mientras hacía un estudio para la escuela, y sinceramente, eso me ayudó. Me di cuenta de que podría expresar mis emociones a través de la música en lugar de la ira. Me sentí mejor durante el día, a pesar de que aún algo me molestaba. A la tarde, vi a mis papás discutir nuevamente y decidí alejarme. Fue difícil, pero también reconfortante saber que no tenía que ser parte de eso. No sé si esto es un avance, pero al menos hoy no grité ni me alteré. Eso es algo.', '¡Qué bien que encontraste consuelo en la música! Buscar actividades que te nutran emocionalmente puede ser una herramienta valiosa. Además, darte el espacio para no involucrarte en la discusión es un gran paso hacia el autocontrol. Felicítate por cuidar de ti mismo y por no dejar que la ira sea la única forma de lidiar con el estrés. Recuerda que cada día es una nueva oportunidad para crecer y aprender. Sigue así, Lucas.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-23', 'audio', 'Día 7: Hoy fue un poco más complicado. La presión de la escuela aumentó, y eso hizo que me sintiera ansioso nuevamente. Recibí comentarios sobre mi trabajo en clase que no fueron los que esperaba, eso me llevó a una especie de crisis de ira. Sentí que estaba volviendo a caer en lo mismo... así que, para liberarme, fui al gimnasio. Hacer ejercicio parece ayudarme a canalizar toda esa energía acumulada. Es raro, nunca pensé que algo como levantar pesas podría hacerme sentir mejor. Mis padres no entendían por qué estaba enojado, pero al menos así no lo saqué con ellos. Parece que aún estoy en la lucha, pero creo que tengo algunas herramientas ahora.', 'Es admirable que encuentres una salida saludable como el ejercicio para manejar tu ira. La actividad física puede ser una herramienta poderosa para liberar la tensión y mejorar tu estado de ánimo. Reconocer los momentos difíciles también es valioso, y es normal regresar a viejas emociones en situaciones estresantes. Lo importante es que estás empezando a identificar qué te ayuda. Cada esfuerzo cuenta, y eso es lo que te lleva a avanzar en tu camino emocional.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-24', 'text', 'Día 8: Hoy me sentí cansado. La semana está siendo larga y el estrés de los exámenes se siente pesado. Intenté compartir cómo me siento con un amigo, pero no sé, sentí que él no lo entendía. En casa, yo estaba en silencio, pero mi madre notó que algo estaba mal. Me preguntó si quería hablar, pero la verdad es que no tengo ganas de hacerlo. La ira está ahí, como una sombra, pero supongo que tengo mis momentos buenos también. Por otro lado, aunque parezca mínima, sentí que tengo más control esta semana; no he pasado los límites, lo cual es un alivio.', 'El cansancio y el estrés pueden hacer que sea aún más difícil lidiar con tus emociones, Lucas. Es comprensible que sientas que no siempre puedes abrirte a los demás. La ira puede manifestarse en momentos de silencia y reflexión, y está bien no tener siempre las palabras correctas. Pasar por momentos de control es realmente un avance, aunque parezca pequeño. Celebra esos logros, y permite que cada día te acerque más a la tranquilidad que buscas.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-27', 'audio', 'Día 9: Hoy hubo un cambio. Hice un esfuerzo consciente por respirar profundamente cuando sentí que la ira comenzaba a surgir. Tuve una discusión con un compañero de clase, pero en lugar de responder con ira, simplemente me retiré y respiré. No sé, estuvo bien y me sentí extraño, como si hubiera ganado una pequeña batalla. En la noche, hablé con mi papá y el simplemente escuchó. Por primera vez, me sentí comprendido. Tal vez no se trate de eliminar la ira por completo, sino de aprender a manejarla. Estoy empezando a aceptar que esto será un proceso largo.', '¡Eso es un gran paso, Lucas! Reconocer tus emociones y encontrar formas saludables de lidiar con la ira es un avance significativo. La habilidad de retirarte y respirar demuestra una gran fortaleza y autoconocimiento. Aprender a manejar, en vez de eliminar, la ira puede transformar tu relación con ella. Es muy positivo que te hayas sentido comprendido por tu papá; contar con apoyo puede hacer toda la diferencia. Así que sigue así, cada día trae nuevas oportunidades de crecimiento.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-29', 'audio', 'Día 10: Hoy fue un día de reflexión. Al revisar la semana, me doy cuenta de lo lejos que he llegado desde el primer día. Claro, tuve momentos de enojo, pero en general, he aprendido a comunicarme mejor incluso si hay días difíciles. La terapia ha sido un espacio útil. A veces me resisto, pero cada vez que me abro, siento alivio. Esta mañana tuve una charla real con mis papás, y por primera vez, no sentí la necesidad de gritar ni de alejarme. Se siente extremadamente bien. Estoy aquí, trabajando en mis emociones y, aunque el camino es largo, tengo algo que aferrarme: la esperanza.', 'Qué hermoso cierre para esta reflexión, Lucas. Es impresionante notar cuánto has evolucionado en tan poco tiempo. Poder comunicarte de manera más efectiva con tus papás es un logro significativo, y es un claro indicativo de tu crecimiento. La esperanza es un motor poderoso en este tipo de proceso. Sigue permitiéndote ser honesto contigo mismo y celebra cada pequeño avance. Refleja este compromiso y confía en que lo que estás haciendo vale la pena.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-15', 'text', 'Día 1: Hoy ha sido un día difícil. Estaba en clase de psicología y de repente sentí que mi corazón empezaba a latir muy rápido. No sé si fue la presión de los exámenes o simplemente no estar preparada. Me sudaban las manos y empecé a sentirme mareada. Cuando finalizó la clase, me fui a la biblioteca y ese fue un error. El lugar estaba lleno y sentía que no podía respirar. Empecé a pensar que todos me miraban, que seguro se daban cuenta de que estaba en crisis. No sé por qué, pero eso me hizo sentir peor. Regresé a casa y hablé con mi mamá sobre lo que me había pasado, pero no creo que pudiera entenderlo realmente. Fue un día agotador y creo que estoy muy asustada por lo que me está pasando. No sé si la terapia va a ayudarme...', 'Valeria, lamento que hoy hayas tenido un día tan abrumador. Es completamente normal sentir ansiedad, especialmente en situaciones de alta presión como las clases. Tu valentía al abrirte sobre lo que sentiste con tu mamá es un paso importante. A veces, compartir nuestras inquietudes puede aliviar la carga emocional. Recuerda que estar en un lugar abarrotado puede desencadenar esos síntomas, pero también es un indicativo de tu valentía al enfrentarte a tus miedos. Cada paso cuenta, incluso cuando parece pequeño.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-17', 'text', 'Día 2: Hoy pensé que las cosas podrían mejorar, pero estaba equivocada. Fui a una reunión de grupo de estudio y, aunque empecé con ánimo, empecé a sentirme incómoda cuando todos comenzaron a hablar de sus planes para el futuro. Sentí que era un tema del que no podía hablar, y eso fue escalando en mi mente. Mi pecho se sentía apretado y tenía esa sensación de no poder respirar. Tuve que salir de la sala abruptamente y me fui al baño a tratar de calmarme. Me miré al espejo y pensé que si no podía lidiar con esto, ¿cómo iba a enfrentar la universidad? Quiero que esto se detenga, pero hoy no me sentí capaz.', 'Es comprensible que hayas tenido un día tan complicado, Valeria. Los momentos en los que sientes que no encajas pueden ser profundamente estresantes. El hecho de que te hayas tomado el tiempo para salir y buscar un lugar más tranquilo demuestra tu autocuidado. A veces, en medio de la angustia, olvidamos que es natural sentirnos perdidos o inseguros sobre el futuro. Recuerda que cada persona tiene su propio camino, y está bien que el tuyo no se sienta claro en este momento. Eres fuerte por reconocer tus emociones.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-18', 'audio', 'Día 3: Hoy decidí que iba a ser diferente, intenté practicar algunas técnicas de respiración que aprendí en la terapia. Cuando me sentí un poco ansiosa antes de una presentación, respiré hondo y conté hasta cuatro. Creo que funcionó, fue un alivio en comparación a los días anteriores. Sin embargo, después de la presentación, sentí que toda la tensión acumulada regresó y me quedé con un nudo en el estómago. Hice un esfuerzo por salir con mis amigos después, pero no pude disfrutar del momento. Aun así, me siento un poco orgullosa de haber manejado mejor la ansiedad. Supongo que son pasos pequeños, pero con un significado grande.', 'Valeria, ¡qué increíble que hayas decidido practicar tus técnicas de respiración! Tomar el control de la situación, aunque sea un pequeño paso, es un logro significativo. La ansiedad puede ser desalentadora, pero reconocer que tu esfuerzo valió la pena, incluso si el nudo en el estómago regresó, es una manera poderosa de avanzar. No te desanimes por lo que no pudiste disfrutar; cada experiencia es parte de tu proceso de aprendizaje. Tienes la capacidad de encontrar formas de mejorar tu bienestar emocional, y hoy has dado un gran paso adelante.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-19', 'text', 'Día 4: Esta mañana me desperté con una sensación pesada. No sé si fue el clima o simplemente no haber dormido bien. Fue un día de clases normales, pero en cada lección esperaba que me diera un ataque de pánico. No sé, incluso cuando mis compañeros estaban riendo, sentí que no encajaba. Volví a la biblioteca después de clases, pero esta vez llevaba mis audífonos y música. Parecía ayudar a aislarme del estrés, pero de igual forma, me rompí a llorar allí. No sé por qué a veces siento que no puedo salir de mi propia cabeza. Aunque a veces creo que siento avances, hay días que me llevan de vuelta.', 'Valeria, lamento que hoy haya sido un día tan pesado. Es normal que haya altibajos en este proceso; algunas veces parece que vamos hacia adelante y otras hacia atrás. La música puede ser una herramienta maravillosa para encontrar un momento de paz en medio del caos, y es comprensible que la soledad a veces surja con más fuerza. Permítete sentir esas emociones, incluso cuando son dolorosas. Lo que sientes es válido y seguirás encontrando maneras de manejarlo, un día a la vez.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-20', 'audio', 'Día 5: Hoy decidí desconectarme un poco de las redes sociales. Me he dado cuenta de que ver a otros actuar normalmente me causa ansiedad. En lugar de eso, fui al parque a dar un paseo. Fue extraño al principio, pero luego realmente me sentí un poco mejor. El aire fresco y la naturaleza parecían calmarme. Hice un esfuerzo consciente por concentrarme en lo que observaba a mi alrededor, en lugar de mis pensamientos negativos. Lo logré, pero al volver a casa, el miedo regresó. Me sentí muy cansada y como si toda la energía que había reunido se desvaneciera. Sabía que esto era parte del proceso, pero, eh... a veces siento que nunca termina.', 'Valeria, me alegra que hayas tomado la decisión de salir al parque y disfrutar del aire fresco. Reconocer que las redes sociales pueden tener un impacto negativo en tu bienestar es un gran paso hacia el autocuidado. Es normal que haya momentos de paz seguidos por el miedo. Ese cambio en tu energía es parte del proceso. Tienes una gran fortaleza al identificar qué puede ayudarte y al dirigir tú misma tu atención hacia lo positivo. Recuerda, cada paso, incluso aquellos que parecen pequeños, está construyendo tu resistencia y capacidad para sobrellevar estos momentos.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-22', 'audio', 'Día 6: No sé qué pensar de hoy. Tuve un día relativamente bueno; asistí a todas mis clases y, aunque sentía un poco de tensión, había logrado sobrellevarlo. Sin embargo, cuando llegué a casa, me ambiento y todo volvió a encadenarse. Las preguntas sobre el futuro y el miedo a no salir adelante empezaron a invadirme. Era como si todo el mero esfuerzo del día se desmoronara. Comencé a tener un ataque de pánico mientras estaba en mi habitación. Llamé a mi mamá y, aunque ella intentó ayudarme, me sentí sola. A veces me pregunto si estoy avanzando o retrocediendo, y eso me frustra mucho.', 'Valeria, lamento que este día haya sido tan turbulento para ti, especialmente después de haber tenido un día que parecía ir bien. Reconocer que las emociones pueden cambiar rápidas e inesperadamente es algo comprensible; incluso esos altibajos pueden ser desgastantes. Hablar con tu mamá muestra lo importante que es apoyarte en las personas que te rodean. No te sientas mal al tener días difíciles; todos atravesamos momentos de lucha. La clave es que estás ahí, continuando el viaje y buscando el apoyo que necesitas. Eso ya es un gran avance.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-23', 'audio', 'Día 7: Hoy decidí hacer algo diferente y fui a una clase de yoga que siempre había querido probar. Me sentía nerviosa al principio, pero fue muy relajante. La instructora era comprensiva y me recordó que está bien no ser perfecta. Al final de la clase, sentí que podía respirar con más facilidad y algo relajada. Sin embargo, cuando llegué a casa hubo una pequeña discusión con mi papá y rápidamente volví a sentir la ansiedad. Es frustrante cómo una pequeña cosa puede hacer que todo lo que construí se desmorone. A veces es difícil encontrar la estabilidad que tanto anhelo.', 'Qué gran decisión valerte por ti misma al probar la clase de yoga, Valeria. Encontrar actividades que te ayuden a sentirte más tranquila es valioso y este tipo de prácticas pueden tener un impacto duradero en tu bienestar emocional. Siento que la discusión con tu papá haya exacerbado tus sentimientos de ansiedad; la vida está llena de esas dificultades inesperadas. Busca lo que te dio satisfacción y relájate sabiendo que es perfecto tener días así. Cada intento de gestionar la ansiedad es un paso hacia tu estabilidad y bienestar.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-25', 'audio', 'Día 8: No sé, hoy ha sido un día un poco agridulce. Tuve una presentación en clase y logré superarlo, aunque sentí la adrenalina durante todo el proceso. Se sintió increíble terminar y escuchar aplausos de mis compañeros, pero luego no pude dejar de pensar en que pronto se acercan los exámenes finales. La presión me está empezando a abrumar de nuevo. Regresé a casa y no tenía energía para estudiar, me sentía bloqueada mentalmente. Al recordar lo de hoy, aunque me emociona que pasé la presentación, siento que no puedo dejar de preocuparme por lo que viene. Es agotador.', 'Valeria, es maravilloso que hayas superado tu presentación; esos aplausos son un reconocimiento a tu esfuerzo y valentía. Es normal sentir una mezcla de emociones, especialmente con la presión de los exámenes finales. Permítete sentir ese agotamiento; es un reflejo del esfuerzo que has puesto. La vida puede ser un equilibrio entre los éxitos y las preocupaciones, y reconocer lo que has logrado es igual de importante. Tómate tu tiempo para procesar tus emociones y no dudes en buscar ayuda si te sientes bloqueada. Estás haciendo un trabajo increíble al enfrentarte a estos desafíos.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-27', 'audio', 'Día 9: Hoy, decidí tomarme una tarde libre y no obligarme a estudiar. Simplemente salí a caminar y exploré un nuevo café que había escuchado. Pedí un helado y disfruté de mi tiempo, aunque los pensamientos de culpa por no haber estudiado estaban constantemente en mi mente. Sin embargo, ¡fue genial darme un merecido descanso! Cuando regresé a casa, no me sentí tan abrumada como esperaba. Tal vez el escapar un poco me ayudó a aclarar la mente. Creo que podría intentar hacer esto más a menudo, aunque la culpa siempre está ahí, supongo que es parte de aprender a cuidarme.', 'Valeria, es realmente admirable que hayas tomado esa decisión de darte un descanso y disfrutar de un momento solo para ti. Reconocer que necesitas cuidar de ti misma es un paso importante en este proceso. Las emociones como la culpa son comunes, pero permitirte momentos así demuestra que estás construyendo tu bienestar. Cada vez que te permites tomar un respiro, te fortalece para enfrentar tus responsabilidades. Sigue explorando lo que te ayude a sentirte mejor; cada paso cuenta en este camino hacia el equilibrio emocional.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-28', 'audio', 'Día 10: Hoy me desperté con un sentimiento mezcla de nerviosismo y determinación. Decidí asistir a una charla sobre estrategias de manejo del estrés en campus. Me sentí un poco fuera de lugar, pero fui valiente y compartí mis experiencias con los asistentes. Fue impresionante escuchar cómo otros también enfrentan sus batallas. Al salir, sentí una gran carga de alivio. Sin embargo, esa noche, al estar sola, el ataque de pánico otra vez vino a mí. No sé, me sentí tan agotada de intentar, y quizás lo que oí hoy se desvaneció con la ansiedad. Luchar contra esto es agotador y a veces se siente como si no tuviera fin.', 'Valeria, tengo que felicitarte por tu valentía al compartir tus experiencias en la charla; eso no es fácil y demuestra un gran crecimiento personal. Es comprensible que, a pesar de los momentos de conexión y alivio, la ansiedad pueda surgir nuevamente. Lo que sientes es válido y es un recordatorio de que este proceso tiene altibajos. Reconocer tus emociones y compartirlas con otros te ayudará a seguir avanzando. A veces es difícil, pero hoy has demostrado que eres capaz de enfrentar tus miedos. Estás haciendo un trabajo admirable, Valeria, y estar en este momento implica seguir creando tu propio camino hacia el bienestar.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-15', 'audio', 'Día 1: Hoy fue un día bastante complicado. Empecé clases de nuevo, y la ansiedad me atacó desde la mañana. Al salir de casa, mi corazón palpitaba como loco, y al pensar en socializar, me dio un nudo en el estómago. En la universidad, durante la primera clase, los profesores pidieron que nos presentáramos y tuve que hacer un esfuerzo enorme para no quedarme callado. Cuando fue mi turno, me temblaban las manos y la voz me salió entrecortada. Me sentí tan pequeño y quise desear que la tierra me tragara. Regresé a casa, y mis padres me preguntaron cómo me había ido, pero solo pude sonreír y decir que todo estaba bien. A veces, siento que estoy atrapado en un ciclo interminable de estas experiencias. No sé si voy a poder seguir así...', 'Hola Mateo, quiero que sepas que es completamente normal sentirte ansioso en situaciones sociales, especialmente al comenzar un nuevo ciclo escolar. Hiciste un gran esfuerzo al presentarte, a pesar de lo incómodo que fue para ti. Es valiente tratar de enfrentar esos momentos, aunque no siempre se sienta bien. Reconocer tus emociones es un primer paso importante. Estoy aquí para ayudarte a seguir explorando estos sentimientos y encontrar formas de manejarlos mejor.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-17', 'audio', 'Día 2: Hoy fue un poco mejor, o eso pensé. Medité un rato por la mañana, y me ayudó a calmarme. En clase, aunque seguía sintiendo nervios, hice un par de preguntas. No eran nada del otro mundo, pero me sentí un poco más seguro. Sin embargo, durante el receso, un grupo de chicos se reía y conversaba, y yo me sentía fuera de lugar. Quería unirme, pero me quedé parado al borde, pensando en mil cosas. Al final del día, salí rápido de la universidad. Aunque hice algo positivo, no pude evitar sentirme un poco triste por no haberme atrevido a acercarme a esos chicos. Me preocupa que esta actitud no me deje hacer amigos realmente.', 'Es muy alentador escuchar que hiciste preguntas en clase, Mateo. Eso sí que es un avance, y deberías sentirte orgulloso de ti mismo. También es normal sentirse fuera de lugar a veces, sobre todo cuando ves a otros socializando. Lo importante es que estuviste presente y te permitiste sentir, incluso cuando era incómodo. Recuerda que construir conexiones lleva tiempo, y estoy aquí para apoyarte a encontrar ese espacio donde te sientas más cómodo.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-18', 'audio', 'Día 3: Hoy me sentí abrumado. Todo lo que hice fue estudiar en casa, pero cada vez que intentaba hacer algo social, como enviar un mensaje a un compañero, mi mente estaba llena de dudas. Pensé que podría invitar a alguien a salir, pero me congelé. “¿Qué van a pensar de mí?”, “¿Y si me rechazan?”. Así que simplemente no lo hice. Pasé la tarde en mi habitación, mirando el teléfono, y me atormenté con esos pensamientos negativos. A veces, desearía poder cambiar mi forma de ser tan rápido como un chasquido de dedos. Es frustrante no poder salir de este ciclo de pensamiento.', 'Mateo, encuentro que lo que sientes es comprensible. Esos pensamientos de duda pueden ser realmente paralizantes. Quiero que sepas que no estás solo en esto, y que esa lucha interna es algo que muchos enfrentan. Hiciste bien al ser consciente de cómo te sentías, aunque sea difícil. No es fácil dar el primer paso hacia el cambio, pero cada día que te enfrentas a esos pensamientos es una oportunidad para hacer algo diferente. Estoy aquí para ayudarte a encontrar maneras de desafiar esos pensamientos negativos.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-20', 'text', 'Día 4: Hoy decidí darme un descanso de la presión de pensar en socializar. Salí a caminar solo y, aunque me sentía un poco extraño caminando por el parque, encontré que el aire fresco me relajaba. Me di cuenta de que puedo disfrutar de mi propia compañía. Al volver a casa, decidí cocinar algo. Fue terapéutico estar en la cocina, y hasta me reí de unos errores que cometí. Sin embargo, al ver fotos de mis amigos en redes sociales, el sentimiento de soledad volvió con fuerza. Fue extraño, como que tenía dos cosas en paralelo: un momento de calma y otro de tristeza.', 'Es genial que tomaste la decisión de cuidar de ti mismo, Mateo. Salir a caminar y disfrutar del aire libre puede ser muy reconfortante. Es normal tener esos altibajos en tus emociones; a veces puedes sentirte bien y, en otras, la soledad puede nublar esos momentos. Lo importante es que encontraste algo que te gusta, como cocinar, y eso es un paso positivo hacia el autocuidado. Estoy aquí para seguir apoyándote en este proceso y encontrar formas de equilibrar esas emociones opuestas.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-22', 'audio', 'Día 5: Hoy fue un desastre. Tenía una clase de grupo, y eso me aterraba. No logré hablar en absoluto y, cuando me hicieron una pregunta, me quedé callado y los demás me miraron. Lo sentí como un juicio. Al salir, excusé todo porque solo era un ejercicio en clase, pero por dentro estaba angustiado. Regresé a casa con la sensación de que no valgo la pena. Quería solo esconderme. A veces, pienso que nunca voy a superarlo. Mis pensamientos están siendo tan oscuros, y no sé cómo encontrar la luz.', 'Mateo, siento mucho que tuviste un día tan difícil. Es completamente naturales sentirte así después de una situación tan incómoda. No poder hablar puede ser increíblemente frustrante, pero quiero que recuerdes que un día difícil no define tu valor ni tu capacidad para cambiar. Todos enfrentamos momentos de inseguridad. Estoy aquí para ayudarte a trabajar a través de estos sentimientos y a encontrar esas pequeñas luces en la oscuridad. Te animo a que continúes enfrentando esos retos con valor.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-24', 'audio', 'Día 6: Hoy di un pequeño paso. En clase, aunque estaba nervioso, decidí participar en un debate. Sí, me costó un montón y sentí que iba a desmayarme, pero logré aportar un par de ideas. Nadie me miró raro, de hecho, pasaron a hablar conmigo luego. Fue un alivio, y por un momento, sentí que valía la pena intentar de nuevo. Sin embargo, todavía tengo miedo de que este tipo de éxito sea solo temporal. Me preocupa caer en la misma trampa de la desesperación si no continúo así.', '¡Qué logro tan significativo, Mateo! Participar en un debate es un gran paso, y deberías sentirte muy orgulloso de ti mismo por haberlo hecho. Es completamente normal dudar de los éxitos, especialmente si has estado luchando, pero quiero recordarte que cada pequeña victoria cuenta. Tu progreso es real y significativo. Estoy aquí para explorar contigo esos miedos que aparecen y ayudarte a fortalecer tu confianza en que puedes seguir avanzando.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-25', 'text', 'Día 7: Hoy me sentí un poco confuso. Pasé un rato revisando mis redes y casi me frustró ver que muchos de mis compañeros parecían tan felices y seguros. Me pregunté por qué no puedo tener lo mismo. Me encontré comparándome con ellos, y eso me hizo volver a sentirme mal. Sin embargo, también hice una llamada a un viejo amigo y hablamos un rato. Estrategias. Fue un buen recordatorio de que no estoy solo. A veces, esos momentos de conexión me dan esperanza, aunque después el bajón vuelve. Es un ciclo raro.', 'Es completamente normal experimentar ese tipo de dudas y comparaciones, Mateo. El mundo en línea a menudo muestra solo lo positivo, lo que puede hacer que te sientas como si estuvieras rezagado, pero lo importante es recordar que cada persona tiene su propia lucha. Hiciste bien al reconectar con un amigo; esos momentos de conexión auténtica son importantes. Estoy aquí para seguir apoyándote y ayudarte a construir esas redes que te den esperanza y fortaleza.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-26', 'audio', 'Día 8: Hoy decidí probar algo nuevo. Asistí a un taller de arte en la universidad, y pensé que sería un buen lugar para relajarme y tal vez conocer a alguien. Cuando llegué, estaba muy nervioso, pero me senté y comencé a pintar. Aunque al principio me sentí un poco fuera de lugar, eventualmente hablé con la persona a mi lado. Hicimos una conexión sobre nuestro amor por el arte, y aunque fue solo una breve charla, me dio un arcoíris de felicidad. No sé, siento que está cambiando algo dentro de mí. Quizás los pequeños pasos sí sumen.', '¡Qué experiencia tan hermosa, Mateo! Asistir a un taller de arte y conectar con alguien es un gran paso fuera de tu zona de confort. Me alegra mucho saber que disfrutaste de la actividad y que esa pequeña conversación te llenó de felicidad. Esas pequeñas interacciones son realmente valiosas y pueden abrir muchas puertas. Estoy aquí para ayudarte a seguir experimentando estos momentos positivos y seguir explorando todo lo que eres capaz de lograr.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-28', 'text', 'Día 9: Hoy fue un día agridulce. Me sentí emocionado porque la interacción en el taller me dio nuevo aliento, y pensé que podía seguir con eso. Pero luego, cuando traté de hablar con un grupo en la biblioteca, me sentí abrumado. No logré articular nada, y me fui antes de que pudieran preguntarme más. Regresé a casa sintiéndome decepcionado. Estoy tratando de recordar el progreso que he hecho, pero a veces siento que solo soy un fracaso. Espero poder encontrar más constancia en mis acciones. La duda me agobia a veces.', 'Mateo, es completamente normal tener altibajos en este viaje. Aunque hoy no resultó como esperabas, es importante que recuerdes que cada interacción, sin importar el resultado, es una oportunidad de aprendizaje. La autocrítica puede ser dura, pero no te defines por un solo momento. Eres un trabajo en progreso, y estoy aquí para apoyarte mientras sigues desarrollando tus habilidades sociales y enfrentando esos miedos. Siempre hay luz en el camino, incluso en los días difíciles.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (3, '2026-06-29', 'audio', 'Día 10: Hoy decidí anotarme en un club de lectura. Suena ridículo, pero sentí que era una forma fácil de entrar en un grupo sin tanta presión. Tenía algunas dudas, pero lo hice. La gente allí fue agradable, y aunque al principio estaba un poco callado, al final de la reunión, un par de personas me invitaron a un café. No puedo decir que me sentí súper cómodo, pero fue un avance. Tal vez la socialización no es tan terrible como pensaba. Estoy comenzando a ver que cada paso que doy vale la pena, aunque me sienta raro al principio.', '¡Mateo, esto es maravilloso! Inscribirte en un club de lectura es una excelente manera de conectarte con otras personas que comparten tus intereses y te ofrece un ambiente más relajado para socializar. Tus sentimientos de incomodidad son completamente válidos, pero el hecho de que te invitaran a tomar un café significa que tu presencia fue apreciada. Estás avanzando, y cada pequeño paso cuenta. Estoy aquí para celebrarlo contigo y seguir fomentando tu confianza en este proceso.', 'completed');
